from pathlib import Path
import json,html,csv,hashlib
from zipfile import ZipFile,ZIP_DEFLATED
root=Path(__file__).parent;r=json.loads((root/'results.json').read_text())
names={'league':'Média da competição','goals8':'Golos, regularização 8','goals4':'Golos, regularização 4','goals8_elo20':'Golos 8 + Elo 20%','goals8_sot25':'Golos 8 + remates enquadrados 25%','goals8_xg25':'Golos 8 + xG 25%'}
rows=''
for year,p in r['periods'].items():
 for m,v in p['all'].items():
  w=v['win65'];rows+=f"<tr><td>{year}</td><td>{names[m]}</td><td>{v['n']}</td><td>{v['logloss']:.5f}</td><td>{v['brier']:.5f}</td><td>{w['hits']}/{w['n']}</td><td>{w['rate']:.1%}</td></tr>" if w['n'] else f"<tr><td>{year}</td><td>{names[m]}</td><td>{v['n']}</td><td>{v['logloss']:.5f}</td><td>{v['brier']:.5f}</td><td>0</td><td>—</td></tr>"
tickets=''
fam={'win':'Vitória 1/2','dc':'Dupla hipótese','win_O15':'Vitória + mais de 1,5','dc_O15':'Dupla hipótese + mais de 1,5'}
for t in r['tickets_probability_only']:
 rate=t['wins']/t['tickets'] if t['tickets'] else 0
 tickets+=f"<tr><td>{t['year']}</td><td>{t['span']} dias</td><td>{fam[t['family']]}</td><td>{t['nlegs']}</td><td>{t['wins']}/{t['tickets']}</td><td>{rate:.1%}</td><td>{t['mean_p']:.1%}</td><td>{t['nonoverlap']['wins']}/{t['nonoverlap']['n']}</td></tr>" if t['tickets'] else ''
train=''.join(f"<tr><td>{names[m]}</td><td>{v['n']}</td><td>{v['logloss']:.5f}</td></tr>" for m,v in r['training_2024'].items())
pairs=''
for year,p in r['periods'].items():
 for kind in ['sot','xg']:
  q=p[f'paired_{kind}_active'];model='goals8_sot25' if kind=='sot' else 'goals8_xg25'
  pairs+=f"<tr><td>{year}</td><td>{kind}</td><td>{q['n']}</td><td>{q['goals8']['logloss']:.5f}</td><td>{q[model]['logloss']:.5f}</td></tr>"
report='''<!doctype html><html lang="pt-PT"><meta charset="utf-8"><title>BigOdds — estudo histórico 2024–2026</title><style>body{font:16px/1.55 system-ui;max-width:1200px;margin:40px auto;padding:0 24px;color:#17242b}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:9px;border-bottom:1px solid #ccd4d8;text-align:left}h1,h2{line-height:1.2}.note{background:#f1f5f7;padding:16px}</style><h1>BigOdds — estudo histórico sem xG e comparações adicionais</h1><p>05-11-2026. Estudo offline, sem alterações de produção e sem chamadas pagas ao fornecedor.</p><div class="note"><strong>Conclusão:</strong> existem milhares de jogos antigos úteis. O protótipo de golos com regularização 4, escolhido pelo menor erro em 2024, reduziu o erro probabilístico face ao protótipo de regularização 8 em 2025 e no bloco de 2026. Isto não demonstra que seja melhor que o modelo completo do LuxTips nem que produza múltiplas rentáveis. <strong>Não há odds históricas arquivadas nesses anos para validar o alvo 8–15.</strong></div><h2>Dados recuperados</h2><p>10.892 jogos FT, de 2023 a 04-11-2026, em dez competições: Primeira Liga, Premier League, La Liga, Bundesliga, Serie A, Ligue 1, Eredivisie, Champions, Liga Europa e Conference. Foram geradas 26.724 previsões de pares jogo/janela, sempre às 08:00 de Lisboa do primeiro dia e abrangendo no máximo três dias. Só os resultados anteriores ao instante de decisão, assumindo conclusão ao fim de duas horas, entraram no histórico.</p><p>2023 serve de aquecimento. A escolha entre quatro candidatos sem xG usa 2024. Em 2025 há 2.344 jogos com previsão no próprio dia e pelo menos 12 jogos anteriores por equipa na competição; 2026 tem 1.829 jogos elegíveis, até 21/10. A exclusão por amostra reduz a cobertura e pode excluir recém-promovidos e algumas equipas europeias. 2025 é ano civil, não a época 2025/26 completa.</p><p>Afinal existe cobertura parcial antiga de remates e xG: foram recuperadas 3.852 linhas de detalhes. A disponibilidade desses dados foi verificada antes de os utilizar. Os campos em falta não foram substituídos por zeros. As datas de importação são posteriores aos jogos: este é um backtest reconstruído por tempo dos eventos, não prova do que o fornecedor disponibilizava historicamente nem de ausência de revisões.</p><h2>Modelos fixados antes de avaliar 2025</h2><p>Modelo Poisson com força ofensiva/defensiva em casa/fora por competição, dados com meia-vida de 180 dias e regularização pela média da liga (8 ou 4 observações). As taxas refletem golos marcados e sofridos antes do jogo. O candidato Elo mistura 20% da distribuição 1X2 de uma referência Elo, atualizada só com resultados anteriores (K=20, vantagem de casa 60 pontos), com 80% do modelo de golos. Remates enquadrados e xG têm peso fixo de 25% nas intensidades, só quando ambas as equipas e a liga têm cobertura suficiente; nos restantes jogos recuam para a base sem esse enriquecimento.</p><p>Os protótipos não são uma reprodução do motor contextual completo em produção. Os coeficientes não foram ajustados depois de observar 2025. A distribuição conjunta de placares é calculada diretamente, pelo que as probabilidades dos combos não são produtos de eventos independentes do mesmo jogo.</p><h2>Escolha em 2024</h2><table><tr><th>Modelo</th><th>Jogos elegíveis</th><th>Log loss 1X2</th></tr>'''+train+'''</table><p>Regra: menor log loss entre Golos 8, Golos 4, Golos 8+Elo20 e Golos 8+remates25. Escolhido: <strong>Golos 4</strong>. A referência da competição e o xG são controlos, não candidatos a essa escolha. Menor log loss/Brier é melhor. Os períodos e vários parâmetros já foram objeto de investigação anterior: a avaliação de 2025 é cronológica mas retrospetiva, não um holdout totalmente cego.</p><h2>Resultados nos anos seguintes</h2><table><tr><th>Ano</th><th>Modelo</th><th>Jogos avaliados</th><th>Log loss 1X2</th><th>Brier 1X2</th><th>Vitórias escolhidas com p≥65%: acertos/n</th><th>Acerto</th></tr>'''+rows+'''</table><p><strong>Os subconjuntos p≥65% não são iguais entre modelos.</strong> A base Golos 8 foi mais seletiva: 115/147 (78,2%) em 2025; Golos 4 escolheu mais jogos: 219/297 (73,7%). A redução do erro probabilístico global não equivale a aumentar a taxa de acerto nesse subconjunto. Não escolher o modelo com o maior acerto de uma coluna depois de observar o teste.</p><p>Diferença Brier Golos4−Golos8 em 2025: −0,003364; intervalo bootstrap 95% por dia, 2.000 reamostragens: [−0,005294; −0,001457]. Em 2026: −0,002091, intervalo [−0,004141; −0,000063]. É evidência favorável neste backtest para esse protótipo face à sua base, não uma garantia de ganhos ou uma comparação com o LuxTips completo.</p><h2>Remates e xG: comparação nos mesmos jogos</h2><table><tr><th>Ano</th><th>Enriquecimento</th><th>Jogos com cobertura</th><th>Log loss base Golos8</th><th>Log loss com enriquecimento</th></tr>'''+pairs+'''</table><p>O xG tem melhoria média pequena nesta implementação; não foi calculado um intervalo de incerteza para essa diferença, pelo que não se declara melhoria estatística comprovada. Remates enquadrados não melhoraram consistentemente o erro. Cobertura, seleção dos jogos e qualidade de medição continuam a importar.</p><h2>Múltiplas: diagnóstico sem preços</h2><p><strong>As linhas seguintes NÃO são múltiplas BigOdds validadas.</strong> Não há odds contemporâneas antigas nem filtro 8–15 nem ROI. Foram escolhidas 5, 8, 9 ou 12 seleções de maior probabilidade dentro de cada família de mercados, em duas ou três datas, com probabilidade individual mínima de 50%, uma seleção por jogo e sem equipas repetidas. A família define-se antecipadamente. Sem preços, uma dupla hipótese domina probabilisticamente a vitória simples e não podemos medir a troca entre risco e retorno.</p><p>Exemplo de 2025, duas datas e nove duplas hipóteses: 39/134 boletins acertaram (29,1%), mas o produto médio das probabilidades foi apenas 21,5%, equivalente a uma odd justa teórica próxima de 4,66, <strong>não uma odd de casa de pelo menos 8</strong>. Não atribuir 29,1% a múltiplas de odd 8–15. Com nove vitórias simples: 3/109; vitória+mais de1,5: 0/38; dupla+mais de1,5: 4/128. Os preços seriam diferentes e estas taxas não permitem declarar uma família superior em rentabilidade.</p><table><tr><th>Ano</th><th>Janela</th><th>Família</th><th>Seleções</th><th>Acertos/boletins</th><th>Acerto</th><th>P conjunta média</th><th>Não sobrepostos: acertos/n</th></tr>'''+tickets+'''</table><p>Janelas móveis e cenários partilham jogos; não somar contagens como observações independentes. As colunas não sobrepostas usam uma âncora fixa no primeiro dia do ano. Todas as famílias correspondem aos oito mercados combinando casa/fora; não foram introduzidos mercados extra.</p><h2>Próximo passo concreto</h2><p>Usar as bases de golos 8 e 4 como concorrentes fixos, com Elo/remates/xG como comparações controladas, e recolher preços reais que permitam avaliar o trade-off probabilidade/odd. Não promover uma versão só pelo acerto de um subconjunto. Sem odds históricas verificáveis, o estudo antigo pode validar qualidade probabilística e cobertura, mas não a execução financeira do BigOdds 8–15. A comparação nesta época com e sem xG deverá continuar nos mesmos jogos, com inputs e odds registados antes do início.</p><h2>Verificação e reprodução</h2><p>Quatro testes passaram: causalidade e normalização das 26.724 previsões; escolha baseada só na tabela de 2024; integridade dos boletins e ausência de odds/ROI inventados; invariância das previsões quando se altera o resultado do próprio jogo. Código, entradas compactas, probabilidades, resumos e logs incluídos. Executar study.py, summarize.py e python -m unittest -v test_study.py, com NumPy instalado.</p><p>Limitações: pressuposto de disponibilidade do resultado duas horas após o início; importações posteriores; eventuais revisões históricas; seleção da amostra; parâmetros e anos já investigados; aproximação Poisson e independência entre jogos; ausência de odds antigas e dos restantes inputs do motor completo. Não houve alterações de produção.</p></html>'''
(root/'BigOdds-estudo-historico.html').write_text(report)
P=json.loads((root/'predictions.json').read_text());chosen=['league','goals8','goals4','goals8_elo20','goals8_sot25','goals8_xg25'].index(r['choice_from_2024'])
with (root/'previsoes-modelo-escolhido.csv').open('w',newline='') as f:
 w=csv.writer(f);w.writerow(['dia_decisao','fixture_id','competicao','inicio_ms','casa_id','fora_id','golos_casa','golos_fora','amostra','H','D','A','1X','X2','1+O15','2+O15','1X+O15','X2+O15'])
 for p in P:
  if p['sample']>=12 and p['start']==__import__('datetime').datetime.fromtimestamp(p['kickoff']/1000,__import__('zoneinfo').ZoneInfo('Europe/Lisbon')).date().isoformat():w.writerow([p['start'],p['id'],p['league'],p['kickoff'],p['home'],p['away'],p['hg'],p['ag'],p['sample']]+p['ps'][chosen])
manifest={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in root.iterdir() if p.suffix in ['.json','.py','.html','.csv','.jsonl']}
(root/'sha256.json').write_text(json.dumps(manifest,indent=2))
with ZipFile(root/'LuxTips-BigOdds-estudo-historico-2024-2026.zip','w',ZIP_DEFLATED) as z:
 for p in root.iterdir():
  if p.suffix in ['.py','.json','.jsonl','.html','.csv']:z.write(p,p.name)
print('Pacote:',(root/'LuxTips-BigOdds-estudo-historico-2024-2026.zip').stat().st_size,'bytes')
